package com.project.system.service;
import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class RbacService{
 @Autowired private JdbcTemplate db;
 private void lock(){db.queryForObject("select id from sys_permission_lock where id=1 for update",Integer.class);}
 private void audit(long actor,String action,long target,String detail){db.update("insert into sys_permission_audit(actor_id,action,target_id,detail) values(?,?,?,?)",actor,action,target,detail);}
 public List<Map<String,Object>> roles(){return db.queryForList("select r.role_id,r.role_name,r.role_key,r.status,r.remark,(select count(*) from sys_user_role ur join sys_user u on u.user_id=ur.user_id where ur.role_id=r.role_id and u.del_flag='0') user_count from sys_role r where r.del_flag='0' order by r.role_sort,r.role_id");}
 private void role(long id){if(db.queryForObject("select count(*) from sys_role where role_id=? and del_flag='0'",Integer.class,id)!=1)throw new IllegalArgumentException("角色不存在");}
 public Map<String,Object> grants(long id){role(id);Map<String,Object> out=new LinkedHashMap<>();out.put("menus",db.queryForList("select menu_id,parent_id,menu_name,menu_type,perms,visible from sys_menu order by parent_id,order_num,menu_id"));out.put("selected",db.queryForList("select menu_id from sys_role_menu where role_id=?",Long.class,id));return out;}
 @Transactional public void grant(long role,Long[] ids,long actor){lock();role(role);if(role==1812120000000001L)throw new IllegalArgumentException("内置管理员授权受保护");Set<Long> selected=new LinkedHashSet<>();Map<Long,Long> parents=new HashMap<>();for(Map<String,Object> row:db.queryForList("select menu_id,parent_id from sys_menu"))parents.put(((Number)row.get("menu_id")).longValue(),((Number)row.get("parent_id")).longValue());if(ids!=null)for(Long id:ids){if(!parents.containsKey(id))throw new IllegalArgumentException("菜单或权限不存在");Set<Long> visited=new HashSet<>();while(id!=null&&id!=0&&visited.add(id)){selected.add(id);id=parents.get(id);}}
 for(Long id:new ArrayList<>(selected)){if(id>8100101L&&id<=8100106L)selected.add(8100101L);if(id>8100201L&&id<=8100206L)selected.add(8100201L);if(id==8100302L)selected.add(8100301L);}
 String old=db.queryForList("select menu_id from sys_role_menu where role_id=?",role).toString();db.update("delete from sys_role_menu where role_id=?",role);for(Long id:selected)db.update("insert into sys_role_menu(role_id,menu_id) values(?,?)",role,id);audit(actor,"GRANT",role,"原授权："+old+"；新授权："+selected);}
 @Transactional public long saveRole(Long id,String name,String key,String status,String remark,long actor){lock();if(name==null||name.trim().isEmpty()||name.length()>30)throw new IllegalArgumentException("角色名称须为1至30字");if(key==null||!key.matches("[a-z][a-z0-9_]{1,29}")||"admin".equals(key))throw new IllegalArgumentException("角色标识须为2至30位小写字母数字下划线，admin为保留标识");if(!Arrays.asList("0","1").contains(status))throw new IllegalArgumentException("角色状态无效");if(remark!=null&&remark.length()>500)throw new IllegalArgumentException("备注不能超过500字");if(id!=null&&id==1812120000000001L)throw new IllegalArgumentException("内置管理员角色受保护");if(db.queryForObject("select count(*) from sys_role where del_flag='0' and (role_name=? or role_key=?) and role_id<>?",Integer.class,name.trim(),key,id==null?-1:id)>0)throw new IllegalArgumentException("角色名称或标识已存在");if(id==null){id=com.project.common.utils.TimeUuidUtil.get16UUID();db.update("insert into sys_role(role_id,role_name,role_key,role_sort,data_scope,status,del_flag,remark,create_by,create_time) values(?,?,?,10,'3',?,'0',?,?,NOW())",id,name.trim(),key,status,remark,String.valueOf(actor));}else{role(id);db.update("update sys_role set role_name=?,role_key=?,status=?,remark=?,update_time=NOW(),update_by=? where role_id=?",name.trim(),key,status,remark,String.valueOf(actor),id);}audit(actor,"ROLE",id,name+" / "+key+" / "+status);return id;}
 public Map<String,Object> users(Long role,String keyword,String member,int page){String where=" where u.del_flag='0'";List<Object>a=new ArrayList<>();if(keyword!=null&&!keyword.trim().isEmpty()){where+=" and (u.user_name like ? or u.login_name like ? or u.phonenumber like ?)";for(int i=0;i<3;i++)a.add("%"+keyword.trim()+"%");}if(role!=null&&"1".equals(member)){where+=" and exists(select 1 from sys_user_role x where x.user_id=u.user_id and x.role_id=?)";a.add(role);}else if(role!=null&&"0".equals(member)){where+=" and not exists(select 1 from sys_user_role x where x.user_id=u.user_id and x.role_id=?)";a.add(role);}Map<String,Object> out=new LinkedHashMap<>();out.put("total",db.queryForObject("select count(*) from sys_user u"+where,Long.class,a.toArray()));List<Object> q=new ArrayList<>();q.add(role==null?-1:role);q.addAll(a);q.add(20);q.add((Math.max(1,Math.min(page,100000))-1)*20);out.put("rows",db.queryForList("select u.user_id,u.user_name,u.login_name,u.phonenumber,u.status,exists(select 1 from sys_user_role x where x.user_id=u.user_id and x.role_id=?) assigned,(select group_concat(r.role_name separator '、') from sys_user_role x join sys_role r on r.role_id=x.role_id where x.user_id=u.user_id and r.del_flag='0') roles from sys_user u"+where+" order by u.user_id limit ? offset ?",q.toArray()));return out;}
 public List<Long> userRoles(long user){return db.queryForList("select role_id from sys_user_role where user_id=?",Long.class,user);}
 @Transactional public void bind(long user,Long[] roles,long actor){lock();if(com.project.system.domain.SysUser.isSuperAdmin(user))throw new IllegalArgumentException("超级管理员绑定受保护");if(db.queryForObject("select count(*) from sys_user where user_id=? and del_flag='0'",Integer.class,user)!=1)throw new IllegalArgumentException("用户不存在");Set<Long> ids=new LinkedHashSet<>();if(roles!=null)for(Long id:roles){role(id);ids.add(id);}String old=userRoles(user).toString();db.update("delete from sys_user_role where user_id=?",user);for(Long id:ids)db.update("insert into sys_user_role(user_id,role_id) values(?,?)",user,id);db.update("update sys_user set role_id=? where user_id=?",ids.isEmpty()?null:ids.iterator().next(),user);audit(actor,"BIND",user,"原角色："+old+"；新角色："+ids);}
 @Transactional public void batch(long role,Long[] users,boolean add,long actor){lock();role(role);if(users==null||users.length==0||users.length>200)throw new IllegalArgumentException("请选择1至200名用户");for(Long user:new LinkedHashSet<>(Arrays.asList(users))){Set<Long> ids=new LinkedHashSet<>(userRoles(user));if(add)ids.add(role);else ids.remove(role);bind(user,ids.toArray(new Long[0]),actor);}}
 public List<Map<String,Object>> audit(){return db.queryForList("select actor_id,action,target_id,detail,created_at from sys_permission_audit order by id desc limit 100");}
}

